diff --git a/src/dec/alpha_dec.c b/src/dec/alpha_dec.c
index 5a514b8..be7f256 100644
--- a/src/dec/alpha_dec.c
+++ b/src/dec/alpha_dec.c
@@ -228,6 +228,13 @@ WEBP_NODISCARD const uint8_t* VP8DecompressAlphaRows(VP8Decoder* const dec,
       }
       if (dec->alpha_dithering > 0) {
         num_rows = height - row;  // decode everything in one pass
+      } else if (dec->alph_dec->method == ALPHA_NO_COMPRESSION) {
+        // Uncompressed alpha has no predictor to resume across calls. Decode a
+        // wider first strip so later macroblock rows find the plane ready.
+        const int kAlphaStripRows = 48;
+        int want = row + kAlphaStripRows;
+        if (want > height) want = height;
+        if (want - row > num_rows) num_rows = want - row;
       }
     }

